def total(*args):
    return sum(args)

print(total(1, 2, 3))
print(total(1, 2, 3, 4, 5))

def info(**kwargs):
    for key, value in kwargs.items():
        print(key, value)

info(name="Анна", age=25)

def f(a, b, *, c):
    return a + b + c

f(1, 2, c=3)

def outer():
    x = 10
    def inner():
        return x
    return inner()

print(outer())

def apply(func, x):
    return func(x)

print(apply(lambda x: x * 2, 5))

@functools.lru_cache(maxsize=None)
def fib(n):
    if n < 2:
        return n
    return fib(n-1) + fib(n-2)

def gen():
    for i in range(3):
        yield i

for x in gen():
    print(x)
